import React, { useRef } from 'react';
import NavBar from '../../Components/NavBar';
import Footer from '../../Components/Footer';
import './design.css';

const Sleeve = () => {
  const sections = {
    puff: useRef(null),
    bishop: useRef(null),
    bell: useRef(null),
    raglan: useRef(null),
    offShoulder: useRef(null),
  };

  const handleScroll = (event) => {
    const selected = event.target.value;
    if (sections[selected]) {
      sections[selected].current.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // Images for each sleeve variety
  const sleeveImages = {
    puff: [
      "/Images/Designs/sleeves/puff1.jpg",
      "/Images/Designs/sleeves/puff2.jpg",
      "/Images/Designs/sleeves/puff3.jpg"
    ],
    bishop: [
      "/Images/Designs/sleeves/bishop1.jpg",
      "/Images/Designs/sleeves/bishop2.jpg"
    ],
    bell: [
      "/Images/Designs/sleeves/bell1.jpg",
      "/Images/Designs/sleeves/bell2.jpg",
      "/Images/Designs/sleeves/bell3.jpg"
    ],
    raglan: [
      "/Images/Designs/sleeves/raglan1.jpg",
      "/Images/Designs/sleeves/raglan2.jpg"
    ],
    offShoulder: [
      "/Images/Designs/sleeves/offshoulder1.jpg",
      "/Images/Designs/sleeves/offshoulder2.jpg"
    ],
  };

  // Longer paragraphs for each sleeve variety
  const sleeveDescriptions = {
    puff: `Puff sleeves are a classic style characterized by fabric gathered at the shoulder and sometimes near the cuff, creating a rounded, voluminous shape. 
    This design adds femininity and elegance to the garment, often used in formal wear, dresses, and blouses. The puffed silhouette is flattering for various body types and can be emphasized with additional volume or subtle puffing depending on the fabric and pattern.`,
    
    bishop: `Bishop sleeves are full-length sleeves gathered tightly at the wrist, creating a billowing, dramatic effect along the arm’s length. 
    Usually wide and flowing from the upper arm, these sleeves provide a romantic and vintage-inspired aesthetic. The cuff is often fitted with buttons or elastic to maintain the gathered look while allowing freedom of movement.`,
    
    bell: `Bell sleeves are named for their shape resembling a bell, flaring out from the shoulder or elbow to create a wide, flowing sleeve. 
    This style enhances the gracefulness of the arm movement and works well with lighter fabrics that drape naturally. Bell sleeves are a popular choice for bohemian and retro-inspired fashion.`,
    
    raglan: `A raglan sleeve extends in one piece fully to the collar, creating a diagonal seam from the underarm to the collarbone. 
    This construction offers greater range of motion and a casual sporty look, commonly seen in athletic wear and casual tops. Raglan sleeves can also be designed with added flair or contrast piping to accentuate the diagonal seam.`,
    
    offShoulder: `Off shoulder sleeves sit below the shoulders, highlighting the collarbone and upper chest area while leaving the shoulders bare. 
    This design creates a sultry, feminine silhouette perfect for summer dresses, tops, and formal wear. Often supported with elastic or fitted bands to keep the garment in place, off shoulder sleeves suit a variety of occasions from casual to dressy.`,
  };

  return (
    <>
      <NavBar />
      <div style={{ padding: '20px', textAlign: 'center' }}>
        <h1>Sleeve Varieties</h1>
        <select onChange={handleScroll} defaultValue="">
          <option value="" disabled>Select Sleeve Variety</option>
          <option value="puff">Puff Sleeve</option>
          <option value="bishop">Bishop Sleeve</option>
          <option value="bell">Bell Sleeve</option>
          <option value="raglan">Raglan Sleeve</option>
          <option value="offShoulder">Off Shoulder Sleeve</option>
        </select>
      </div>

      <div style={{ padding: '20px' }}>
        {Object.entries(sleeveImages).map(([key, images]) => (
          <section key={key} ref={sections[key]} id={key} style={{ marginBottom: '50px' }}>
            <h2>{key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())} Sleeve</h2>
            <p style={{ maxWidth: '700px', lineHeight: 1.6, color: '#444' }}>{sleeveDescriptions[key]}</p>
            <div style={{ display: 'flex', gap: '10px', overflowX: 'auto' }}>
              {images.map((src, i) => (
                <img key={i} src={src} alt={`${key} sleeve design ${i+1}`} style={{ width: '200px', height: 'auto', borderRadius: '8px' }} />
              ))}
            </div>
          </section>
        ))}
      </div>

      <Footer />
    </>
  );
};

export default Sleeve;
